ExamService::ExamService(infrastructure::storage::ExamRepository &repository,
application::services::SubscriptionService &subscriptionService)
: repository_(repository), subscriptionService_(subscriptionService)
{
}

Json::Value ExamService::listExams(const std::string &family,
                                   const std::string &level,
                                   const std::string &year,
                                   const std::string &sort) const
{
    auto exams = repository_.listExams();
    exams.erase(std::remove_if(exams.begin(), exams.end(), [&](const domain::ExamSummary &item) {
                   // A JSON placeholder is not a usable paper. Keep unfinished files in the
                   // content repository, but never advertise them through the public library.
                   if (item.questionCount <= 0)
                   {
                       return true;
                   }
                   if (!family.empty() && item.family != family)
                   {
                       return true;
                   }
                   if (!level.empty() && item.level != level)
                   {
                       return true;
                   }
                   if (!year.empty() && item.year != year)
                   {
                       return true;
                   }
                   return false;
               }),
               exams.end());

    if (sort == "date_asc")
    {
        std::sort(exams.begin(), exams.end(), [](const auto &a, const auto &b) {
            return std::tie(a.year, a.session) < std::tie(b.year, b.session);
        });
    }
    else if (sort == "level")
    {
        std::sort(exams.begin(), exams.end(), [](const auto &a, const auto &b) {
            return std::tie(a.family, a.level, a.year, a.session) < std::tie(b.family, b.level, b.year, b.session);
        });
    }
    else
    {
        std::sort(exams.begin(), exams.end(), [](const auto &a, const auto &b) {
            return std::tie(a.year, a.session, a.family, a.level) > std::tie(b.year, b.session, b.family, b.level);
        });
    }

    Json::Value out(Json::arrayValue);
    for (const auto &item : exams)
    {
        out.append(item.toJson());
    }
    return out;
}

Json::Value ExamService::groupedByLevel() const
{
    Json::Value grouped(Json::objectValue);
    for (const auto &exam : repository_.listExams())
    {
        if (exam.questionCount <= 0)
        {
            continue;
        }
        grouped[exam.family][exam.level].append(exam.toJson());
    }
    return grouped;
}

Json::Value ExamService::getExam(const std::string &examId, const std::string &userId) const
{
    // First check if the exam exists by peeking at the index
    const auto &exams = repository_.listExams();
    const auto it = std::find_if(exams.begin(), exams.end(),
                                 [&](const domain::ExamSummary &s) { return s.id == examId; });
    if (it != exams.end())
    {
        if (it->questionCount <= 0)
        {
            throw common::AppException("EXAM_UNAVAILABLE", "Exam content is not published yet", drogon::k404NotFound);
        }
        subscriptionService_.requireAccess(userId, it->accessLevel);
    }
    auto exam = repository_.getExamById(examId);
    if (exam["exam_info"].get("paper_type", exam.get("paper_type", "")).asString() == "diagnostic")
    {
        int total = 0;
        // Keep section indexes stable for existing drafts and answer history.
        for (auto &section : exam["exam_info"]["sections"])
        {
            const auto usable = [](const Json::Value &question) {
                const auto &answer = question.isMember("correct_answer") ? question["correct_answer"] : question["answer"];
                return question.get("has_ans", true).asBool() && !answer.isNull()
                    && (!answer.isString() || !answer.asString().empty())
                    && question["options"].isArray() && !question["options"].empty();
            };
            const auto filter = [&](Json::Value &questions) {
                Json::Value kept(Json::arrayValue);
                for (const auto &question : questions) if (usable(question)) kept.append(question);
                questions = std::move(kept);
            };
            filter(section["questions"]);
            for (auto &passage : section["passages"]) filter(passage["questions"]);
            std::unordered_set<std::string> ids;
            for (const auto &question : section["questions"]) ids.insert(question["id"].asString());
            for (const auto &passage : section["passages"])
                for (const auto &question : passage["questions"]) ids.insert(question["id"].asString());
            if (ids.empty()) {
                section["diagnostic_excluded"] = true;
                section["passages"] = Json::Value(Json::arrayValue);
            }
            total += static_cast<int>(ids.size());
        }
        exam["exam_info"]["diagnostic_total_questions"] = total;
        auto title = exam["exam_info"].get("title", "").asString();
        const std::string open = "（", close = "题）";
        const auto begin = title.rfind(open);
        if (begin != std::string::npos) {
            const auto end = title.find(close, begin + open.size());
            if (end != std::string::npos && std::all_of(title.begin() + begin + open.size(), title.begin() + end, [](unsigned char c) { return c >= '0' && c <= '9'; }))
                title.replace(begin, end + close.size() - begin, open + std::to_string(total) + close);
        }
        exam["exam_info"]["title"] = title;
    }
    return exam;
}

void ExamService::createOrUpdateExam(const std::string &examId, const Json::Value &payload)
{
    repository_.saveExam(examId, payload);
}

void ExamService::deleteExam(const std::string &examId)
{
    repository_.deleteExam(examId);
}

